    const slot = context.getStore();
    if (!slot || held.get(slot.address) !== slot || !available.includes(slot.address))
      throw new FacilitatorError('SETTLEMENT_SIGNER_CONTEXT_REQUIRED',503);
    return slot.address;
  };
