          ...operation(), before: query.get('before') ?? '', limit: limit(),
        });
        else if (url.pathname === '/api/provider-lookup') result = await model.providerLookup({ ...selected(), id: query.get('id') });
        else if (url.pathname === '/api/provider-response') {
