  const sourceHashes = new Set(state.pages.map(page => page.sourceSha256));
  for (const args of inputs) {
    need(obj(args) && typeof args.page === 'string' && args.page.length > 0 &&
      typeof args.intent === 'string' && /^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$/.test(args.intent),
      'Page path and stable independent original buyer intent required');
    need(state.pages.length === 0 ? args.cursor === undefined : args.cursor === state.nextCursor,
      'Supply exactly the previous original page.nextCursor as --cursor');
    need(!intents.has(args.intent), 'Buyer intent already recorded');
    const source = await bounded(resolve(args.page));
    const payload = JSON.parse(new TextDecoder('utf8', { fatal: true }).decode(source));
    // Validate the complete next-page transition before creating its archive.
    const next = continuation(state, payload, args.cursor ?? null);
    const evidenceSha256 = args.evidence ? sha(await bounded(resolve(args.evidence))) : null;
    const sourceSha256 = sha(source);
    need(!sourceHashes.has(sourceSha256), 'Page payload already recorded');
    const record = { schema: 'stellar-forge.buyer-page-archive.v1',
      index: state.pages.length, previous: state.chain, intent: args.intent,
      requestCursor: args.cursor ?? null, sourceSha256, evidenceSha256,
      signature: next.check.signature, payload };
    const archive = { ...record, chain: sha(compact(record)) };
    const encoded = JSON.stringify(archive) + '\n';
    const archiveBytes = Buffer.byteLength(encoded);
    need(archiveBytes <= MAX_INPUT + 4096 && state.archiveBytes + archiveBytes <= MAX_ARCHIVE,
      'Private page archive exceeds individual or total byte limit');
    const path = join(out, 'pages', pageName(state.pages.length));
    await immutableFile(out, path, encoded);
    acceptRecord(state, archive, next, archiveBytes, false);
    intents.add(args.intent); sourceHashes.add(sourceSha256);
  }
  const current = await scan(out, { retainPayload: false });
  return summary(current, 'PAGES_ACCEPTED');
}

function summary(state, action) {
  return { action, dataset: state.name, snapshot: state.snapshot,
    pages: state.pages.length, rows: state.count, total: state.total,
    complete: state.pages.length > 0 && state.nextCursor === null,
    nextCursor: state.nextCursor, finalized: state.finalized,
    lastRecordDigest: state.chain, ...(state.semantics ? { semantics: state.semantics } : {}) };
}

function csvCell(value) {
  if (value === null) return '';
  let text = String(value);
  if (typeof value === 'string' && /^[\x00-\x20]*[=+@-]/.test(text)) text = "'" + text;
  return '"' + text.replaceAll('"', '""') + '"';
}
const escapeHtml = x => String(x).replace(/[&<>"']/g, c => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
})[c]);
function html(state, manifest) {
  const details = [
    ['Dataset', state.name], ['Snapshot', state.snapshot], ['Rows', state.count],
    ['Pages', state.pages.length], ['Original response chain', state.chain],
    ['Selected fields', state.fields.join(', ')], ['Equality filters', compact(state.filters)],
    ['Range filters', compact(state.ranges)],
    ['Result order', state.order ? compact(state.order) : 'csv-record-order'],
    ['Original query hash', state.queryHash],
    ['Data files', 'dataset.jsonl · dataset.csv'],
    ...(state.semantics ? [['Reviewed source meaning', state.semantics.sha256],
      ['Meaning definition', state.semantics.definitionSha256],
      ['Retained data dictionary', 'semantics.json — full published column meanings, units, keys and URI templates']] : []),
    ['Acceptance', 'Operator review only; source response and digest are not chain finality'],
  ];
  const lines = details.map(([k, v]) => '<div><dt>' + escapeHtml(k) + '</dt><dd>' + escapeHtml(v) + '</dd></div>').join('');
  return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<title>Buyer dataset delivery review</title><style>body{margin:0;background:#f7f7f7;color:#182026;font:15px system-ui,Arial}' +
    'main{max-width:920px;margin:52px auto;padding:28px;background:white;border:1px solid #cbd2d6}' +
    'h1{font-size:24px;font-weight:650;margin:5px 0 4px}small{color:#56636b}dl{display:grid;grid-template-columns:1fr 1fr;gap:13px}' +
    'dl div{border-top:1px solid #dce0e3;padding:12px 4px}dt{color:#56636b;font-size:12px;text-transform:uppercase;letter-spacing:.05em}' +
    'dd{margin:6px 0;overflow-wrap:anywhere}p{line-height:1.55}.foot{border-top:1px solid #dce0e3;padding-top:16px;color:#56636b}</style>' +
    '<main><small>STELLAR FORGE / SF100 / PRIVATE BUYER REVIEW</small><h1>Dataset delivery package</h1>' +
    '<p>Original SF30 paginated response files were stitched in their original response order, including any selected sort. Review the query below, the local manifest and each independent SF88 buyer operation before commercial use.</p>' +
    '<dl>' + lines + '</dl><p class="foot">Hashes establish local source custody, not seller identity, accepted payment, transfer finality, contract, or revenue. CSV strings with spreadsheet formula prefixes are neutralized. JSONL preserves typed source rows.</p></main></html>';
}

async function finalize(out) {
  const state = await scan(out, { retainPayload: false });
  need(state.pages.length > 0 && state.nextCursor === null &&
    state.count === state.total, 'All original pages must be present');
  const files = ['dataset.jsonl', 'dataset.csv', 'review.html', 'manifest.json',
    ...(state.semantics ? ['semantics.json'] : [])];
  const jsonPath = join(out, files[0]), csvPath = join(out, files[1]);
  let jsonHandle, csvHandle, jsonBytes = 0, csvBytes = 0;
  const created = [];
  const jsonDigest = createHash('sha256'), csvDigest = createHash('sha256');
  async function createOutput(path) {
    const temporary = join(out, '.sf100-' + basename(path) + '-' + randomUUID());
    const handle = await open(temporary, 'wx', 0o600);
    try {
      const info = await handle.stat();
      created.push({ path: temporary, destination: path, dev: info.dev, ino: info.ino });
      return handle;
    } catch (error) {
      await handle.close().catch(() => {});
      throw error;
    }
  }
  async function writeOutput(path, content) {
    const handle = await createOutput(path);
    try { await handle.writeFile(content, { encoding: 'utf8' }); await handle.sync(); }
    finally { await handle.close(); }
  }
  try {
    jsonHandle = await createOutput(jsonPath);
    csvHandle = await createOutput(csvPath);
    async function push(handle, digest, content, kind) {
      const size = Buffer.byteLength(content);
      if (kind === 'json') jsonBytes += size; else csvBytes += size;
      need(jsonBytes + csvBytes <= MAX_EXPORT, 'Export exceeds private output byte limit');
      digest.update(content); await handle.writeFile(content, { encoding: 'utf8' });
    }
    await push(csvHandle, csvDigest, state.fields.map(csvCell).join(',') + '\r\n', 'csv');
    for (const expected of state.pages) {
      const { archive } = await readArchive(out, expected.index);
      need(archive.chain === expected.chain && archive.previous === expected.previous,
        'Page archive changed after delivery review: ' + pageName(expected.index));
      const rows = archive.payload.rows;
      await push(jsonHandle, jsonDigest, rows.map(x => JSON.stringify(x) + '\n').join(''), 'json');
      await push(csvHandle, csvDigest,
        rows.map(row => state.fields.map(f => csvCell(row[f])).join(',') + '\r\n').join(''), 'csv');
    }
    await jsonHandle.sync(); await jsonHandle.close(); jsonHandle = null;
    await csvHandle.sync(); await csvHandle.close(); csvHandle = null;
    const manifest = {
      schema: 'stellar-forge.buyer-delivery-manifest.v1',
      dataset: { name: state.name, snapshot: state.snapshot, rows: state.count,
        projectedFields: state.fields, filters: state.filters, ranges: state.ranges,
        order: state.order ?? 'csv-record-order', originalQueryHash: state.queryHash,
        originalQuerySignature: state.pages[0].signature },
      sourcePages: state.pages.map(x => ({index: x.index, intent: x.intent,
        sourceSha256: x.sourceSha256, evidenceSha256: x.evidenceSha256,
        recordDigest: x.chain, rows: x.returned,
        requestedCursor: x.requestCursor})),
      chainDigest: state.chain,
      outputs: { 'dataset.jsonl': {sha256:jsonDigest.digest('hex'), bytes:jsonBytes},
        'dataset.csv': {sha256:csvDigest.digest('hex'), bytes:csvBytes} },
      paymentStatus: 'NOT_INFERRED_FROM_SOURCE_HTTP_OR_LOCAL_HASHES',
      nextStep: 'Owner reviews independent original SF88 evidence and settlement before any paid-delivery claim',
    };
    if (state.semantics) {
      const dictionary = JSON.stringify(state.semanticDocument, null, 2) + '\n';
      const bytes = Buffer.byteLength(dictionary);
      need(bytes <= MAX_INPUT && jsonBytes + csvBytes + bytes <= MAX_EXPORT,
        'Retained semantic dictionary exceeds the private output byte limit');
      await writeOutput(join(out, 'semantics.json'), dictionary);
      manifest.semantics = { ...state.semantics, file: 'semantics.json',
        selectedFields: state.fields,
        scope: 'PUBLISHED_DATASET', typedRowsFile: 'dataset.jsonl' };
      manifest.outputs['semantics.json'] = { sha256: sha(dictionary), bytes };
    }
    const review = html(state, manifest);
    await writeOutput(join(out, 'review.html'), review);
    manifest.outputs['review.html'] = { sha256:sha(review), bytes:Buffer.byteLength(review) };
    await writeOutput(join(out, 'manifest.json'), JSON.stringify(manifest, null, 2) + '\n');
    // Data and review files commit first; the complete original manifest commits last.
    for (const file of created) await publishStaged(out, file.path, file.destination);
    return { ...summary({ ...state, finalized: true }, 'EXPORTED'), output:out, outputs:manifest.outputs };
  } catch (error) {
    if (jsonHandle) await jsonHandle.close().catch(() => {});
    if (csvHandle) await csvHandle.close().catch(() => {});
    for (const file of created) {
      const current = await lstat(file.path).catch(() => null);
      // A competing finalizer's EEXIST must never delete its output. A replaced
      // path likewise belongs to another writer, even if we created the old one.
      if (current?.isFile() && !current.isSymbolicLink() &&
          current.dev === file.dev && current.ino === file.ino)
        await rm(file.path, { force:true }).catch(() => {});
    }
    throw error;
  }
}

export { init, append, appendMany, scan, finalize, checkPage, checkCursor,
  immutableFile as retainDeliveryFile, publishStaged as publishDeliveryFile, retirePublishedLinks as reconcileDeliveryFile,
  MAX_INPUT as MAX_DATASET_PAGE_BYTES, MAX_PAGES as MAX_DATASET_PAGES };
if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
  try {
    const args = argumentsOf(process.argv.slice(2));
    const out = resolve(args.out);
    if (args.command === 'init') message(await init(out));
    if (args.command === 'append') message(await append(out, args));
    if (args.command === 'status') message(summary(await scan(out, { retainPayload: false }), 'STATUS'));
    if (args.command === 'finalize') message(await finalize(out));
  } catch (error) {
    process.stderr.write('SF100: ' + error.message + '\n'); process.exitCode = 1;
  }
}

#!/usr/bin/env node
// MIT. Private merchant receiving review over original source and public reads.
import { readFile, open, mkdir, rm, stat } from 'node:fs/promises';
import { resolve, join, isAbsolute } from 'node:path';
import { pathToFileURL } from 'node:url';
import { merchantReadinessHtml, merchantReadinessCsv } from './merchant.mjs';
import { inspectMerchantReceiving, compareMerchantReadiness } from './receiving-session.mjs';
import { sha256 } from './readiness.mjs';

const HELP = `Usage: node merchant-cli.mjs --config SELLER_JSON --out NEW_PRIVATE_DIRECTORY
  [--asset-map ASSET_MAP_JSON] [--origin ACTUAL_SELLER_ORIGIN] [--rpc-map RPC_MAP_JSON]
  [--https-proxy-env ENV_NAME] [--timeout-ms 12000] [--fee-operations 0]
  [--previous PREVIOUS_REVIEW_DIRECTORY] [--from-capture RETAINED_REVIEW_DIRECTORY]

Saved operator desk: merchant-readiness workspace --directory /absolute/private/desk
  [--port 8408] [--base-path /merchant/receiving]

Reviews every original SF30 option using native token reads and the original SAC
receiving evaluator. Existing exact asset maps are accepted; other SAC identities
are resolved from their deployed metadata and verified with the native SDK.
Writes private review.json, review.html, options.csv, plan.json, asset-map.json,
capture.json and manifest.json. Replay makes the same captured requests offline.
Exit 0: all recipients ready. Exit 2: merchant action/configuration/source review.
Exit 1: provider read failed. Exit 3: invalid input or output failure.
Guide: MERCHANT_READINESS.md`;

async function jsonInput(path) {
  const absolute = resolve(path), info = await stat(absolute);
  if (!info.isFile() || info.size > 1024*1024) throw new Error('INPUT_MUST_BE_JSON_FILE_UNDER_1_MIB');
  const bytes = await readFile(absolute);
  if (bytes.length > 1024*1024) throw new Error('INPUT_TOO_LARGE');
  return {json:JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes)),
    source:{path:absolute,bytes:bytes.length,sha256:sha256(bytes)}};
}

/** Reuse the original explicit CONNECT/TLS transport only when requested. */
export async function createReadinessFetch(proxyEnv, {environment = process.env, timeoutMs = 12000} = {}) {
  if (proxyEnv === undefined) return globalThis.fetch;
  if (!/^[A-Za-z_][A-Za-z0-9_]{0,127}$/.test(proxyEnv) || typeof environment[proxyEnv] !== 'string')
    throw new Error('EXPLICIT_PROXY_ENVIRONMENT_REQUIRED');
  const {createPublicHttpsFetch,normalizeBuyerTransport,resolveBuyerProxy} = await import('../sf31-buyer-client/public-transport.mjs');
  // Resolve this caller's environment now; the original transport receives the
  // same verified proxy URL and retains the exact target origin/TLS identity.
  const transports = new Map();
  return (url, init) => {
    const origin = new URL(url).origin;
    if (!transports.has(origin)) {
      const profile = normalizeBuyerTransport({mode:'explicit-connect',origin,proxyEnv});
      resolveBuyerProxy(profile,environment);
      transports.set(origin,createPublicHttpsFetch({timeoutMs,
        trustedProxy:{mode:'explicit-connect',origin,proxyUrl:environment[proxyEnv]}}));
    }
    return transports.get(origin)(url,init);
  };
}

export async function writeMerchantReview(directory, report, sources, bundle) {
  if (!isAbsolute(directory) || resolve(directory) !== directory) throw new Error('ABSOLUTE_NORMALIZED_OUTPUT_REQUIRED');
  // Own the directory only after this exclusive creation succeeds.
  await mkdir(directory,{mode:0o700});
  try {
    const files = {'review.json':JSON.stringify(report,null,2)+'\n','review.html':merchantReadinessHtml(report),
      'options.csv':merchantReadinessCsv(report),...(bundle ? {
        'plan.json':JSON.stringify(bundle.plan,null,2)+'\n',
        'asset-map.json':JSON.stringify(bundle.resolvedAssetMap,null,2)+'\n',
        'capture.json':JSON.stringify(bundle.capture,null,2)+'\n'} : {})};
    const manifest = {schema:'stellar-forge.merchant-readiness-manifest.v1',createdAt:new Date().toISOString(),
      sources,planDigest:report.planDigest,files:Object.entries(files).map(([name,text])=>
        ({name,bytes:Buffer.byteLength(text),sha256:sha256(text)}))};
    files['manifest.json'] = JSON.stringify(manifest,null,2)+'\n';
    for (const [name,text] of Object.entries(files)) {
      const handle = await open(join(directory,name),'wx',0o600);
      try { await handle.writeFile(text); await handle.sync(); } finally { await handle.close(); }
    }
    return manifest;
  } catch (error) {
    await rm(directory,{recursive:true,force:true});
    throw error;
  }
}

/** Resolve only named files whose exact bytes are committed by the private manifest. */
export async function readMerchantBundle(directory, name) {
  if (!['review.json','capture.json'].includes(name)) throw new Error('INVALID_BUNDLE_MEMBER');
  const root = resolve(directory), manifest = await jsonInput(join(root,'manifest.json'));
  if (manifest.json.schema !== 'stellar-forge.merchant-readiness-manifest.v1' || !Array.isArray(manifest.json.files))
    throw new Error('INVALID_MERCHANT_MANIFEST');
  const matches = manifest.json.files.filter(file=>file.name === name);
  if (matches.length !== 1) throw new Error('MANIFEST_MEMBER_MISSING');
  const expected = matches[0], path = join(root,name), info = await stat(path), max = name === 'capture.json' ? 80*1024*1024 : 8*1024*1024;
  if (!info.isFile() || !Number.isSafeInteger(expected.bytes) || expected.bytes < 0 || expected.bytes > max || info.size !== expected.bytes)
    throw new Error('MANIFEST_SIZE_MISMATCH');
  const bytes = await readFile(path);
  if (bytes.length !== expected.bytes || sha256(bytes) !== expected.sha256) throw new Error('MANIFEST_DIGEST_MISMATCH');
  return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
}

export async function run(argv = process.argv.slice(2)) {
  if (argv[0] === 'workspace') {
    const {main} = await import('./workspace/server.mjs');
    await main(argv.slice(1)); return 0;
  }
  if (argv.length === 0 || argv.includes('--help')) { console.log(HELP); return 0; }
  const values = new Map(), allowed = new Set(['--config','--asset-map','--out','--rpc-map',
    '--https-proxy-env','--timeout-ms','--fee-operations','--origin','--previous','--from-capture']);
  for (let index = 0; index < argv.length; index += 2) {
    if (!allowed.has(argv[index]) || values.has(argv[index]) || !argv[index+1] || argv[index+1].startsWith('--'))
      throw new Error('INVALID_COMMAND_ARGUMENT');
    values.set(argv[index],argv[index+1]);
  }
  for (const key of ['--config','--out']) if (!values.has(key)) throw new Error('MISSING_REQUIRED_ARGUMENT');
  const number = (key,fallback) => {
    if (!values.has(key)) return fallback;
    if (!/^(0|[1-9]\d{0,8})$/.test(values.get(key))) throw new Error('INVALID_NUMERIC_ARGUMENT');
    return Number(values.get(key));
  };
  const [assets,rpc,capture,previous] = await Promise.all([
    values.has('--asset-map') ? jsonInput(values.get('--asset-map')) : null,
    values.has('--rpc-map') ? jsonInput(values.get('--rpc-map')) : null,
    values.has('--from-capture') ? readMerchantBundle(values.get('--from-capture'),'capture.json') : null,
    values.has('--previous') ? readMerchantBundle(values.get('--previous'),'review.json') : null,
  ]);
  const timeoutMs = number('--timeout-ms',12000), feeOperations = number('--fee-operations',capture?.feeOperations ?? 0);
  const fetchImpl = capture ? undefined : await createReadinessFetch(values.get('--https-proxy-env'),{timeoutMs});
  const bundle = await inspectMerchantReceiving({configPath:values.get('--config'),origin:values.get('--origin'),
    assetMap:assets?.json,rpcEndpoints:rpc?.json,timeoutMs,feeOperations,fetchImpl,capture:capture ?? undefined,liveTransport:!capture});
  const report = bundle.report;
  if (previous) report.comparison = compareMerchantReadiness(previous,report);
  const output = values.get('--out');
  await writeMerchantReview(output,report,{seller:report.configuration,
    ...(assets ? {assetMap:assets.source} : {}),...(rpc ? {rpcMap:rpc.source} : {})},bundle);

  console.log(JSON.stringify({status:report.status,...report.summary,output}));
  return report.summary.readFailed ? 1 : report.summary.ready === report.summary.options ? 0 : 2;
}

if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
  // Finish this module before the workspace imports its original bundle helpers.
  // Awaiting the dynamic workspace import here would form a top-level-await cycle.
  run().then(code => { process.exitCode = code; }, error => {
    // Provider URLs and bodies may contain credentials. Emit stable codes only.
    const code = error.code ?? error.message;
    console.error(JSON.stringify({error:typeof code === 'string' && /^[A-Z0-9_]{1,100}$/.test(code) ? code : 'MERCHANT_READINESS_FAILED'}));
    process.exitCode = 3;
  });
}

