  check(data.contract().toXDR('base64') === expectedData.contract().toXDR('base64') &&
    data.key().toXDR('base64') === expectedData.key().toXDR('base64') &&
    data.durability().value === expectedData.durability().value, 'RPC_CONTRACT_DATA_MISMATCH');
