    const row = { name, type: cube.type === 'view' ? 'view' : 'cube',
      title: typeof cube.title === 'string' ? text(cube.title, 'Cube title', 2048) : name,
      measures: [], dimensions: [], segments: [] };
    for (const kind of ['measures', 'dimensions', 'segments']) {
      const list = cube[kind] ?? [];
      if (!Array.isArray(list)) fail(`Cube ${name} ${kind} must be an array`);
      for (const member of list) {
        if (!plain(member)) fail('Invalid Cube member metadata');
        const memberName = text(member.name, 'Cube member name', 512);
        if (hidden || member.public === false || member.isVisible === false) { excludedMembers++; continue; }
        if (members.has(memberName)) fail(`Ambiguous Cube member metadata: ${memberName}`);
        if (members.size >= 100000) fail('Cube metadata exceeds 100000 public members');
        const granularities = new Set(BASE_GRANULARITIES);
        if (member.granularities !== undefined) {
          if (!Array.isArray(member.granularities)) fail(`Invalid granularities metadata: ${memberName}`);
          for (const item of member.granularities) granularities.add(text(typeof item === 'string' ? item : item?.name, 'Granularity name', 128));
        }
        const record = { name: memberName, cube: name, kind,
          type: member.type === undefined ? null : text(member.type, 'Member type', 64),
          title: typeof member.title === 'string' ? text(member.title, 'Member title', 2048) : memberName,
          ...(member.type === 'time' ? { granularities: [...granularities] } : {}) };
        members.set(memberName, record); row[kind].push(record);
      }
    }
    if (!hidden) cubes.push(row);
  }
  return { cubes, members, excludedMembers };
}

export function inspectCubeMetadata(raw) {
  const catalog = compileCubeMetadata(raw);
  return { schema: 'stellar-forge.cube-member-catalog.v1', cubeCount: catalog.cubes.length,
    memberCount: catalog.members.size, excludedMembers: catalog.excludedMembers, cubes: catalog.cubes };
}

/** Validate the supported single-result query profile before original compilation. */
export function bindCubeReport(catalog, report, reportId) {
  const used = new Map(), inputs = report.inputs;
  const error = message => fail(`${reportId}: ${message}`);
  const member = (name, kinds, where, allowGranularity = false) => {
    if (typeof name !== 'string') error(`${where} needs a fixed member name`);
    let entry = catalog.members.get(name), granularity;
    if (!entry && allowGranularity) {
      const dot = name.lastIndexOf('.');
      entry = catalog.members.get(name.slice(0, dot)); granularity = name.slice(dot + 1);
      if (entry?.type !== 'time' || !entry.granularities.includes(granularity)) entry = undefined;
    }
    if (!entry || !kinds.includes(entry.kind)) error(`${where} member absent or wrong kind in saved /meta: ${name}`);
    used.set(entry.name, entry);
    return entry;
  };
  const scalar = (value, types, where) => {
    if (parameter(value)) {
      if (!types.includes(inputs[value.$param]?.type)) error(`${where} requires ${types.join('/')} input`);
      return;
    }
    if (typeof value !== 'string' && value !== null) error(`${where} requires string values`);
    if (typeof value === 'string') text(value, where);
  };
  const dateRange = (value, where) => {
    if (typeof value === 'string') { text(value, where); return; }
    if (!Array.isArray(value) || value.length < 1 || value.length > 2) error(`${where} requires one or two dates, or a fixed relative range`);
    for (const item of value) {
      scalar(item, ['date'], where);
      if (item === null) error(`${where} dates cannot be null`);
    }
    const params = value.filter(parameter).map(item => item.$param);
    if (params.length && !(value.length === 1 || params.length === 2 && params[0] === params[1])) {
      if (params.length !== 2 || report.range?.start !== params[0] || report.range?.end !== params[1])
        error(`${where} public start/end dates require the matching original range guard`);
    }
  };
  const list = (value, kinds, where, allowGranularity = false) => {
    if (!Array.isArray(value) || value.length > 256 || new Set(value).size !== value.length) error(`Invalid ${where} list`);
    for (const name of value) member(name, kinds, where, allowGranularity);
  };
  const filter = (value, depth = 0) => {
    if (!plain(value) || depth > 16) error('Invalid filter object');
    if (own(value, 'and') || own(value, 'or')) {
      const op = own(value, 'and') ? 'and' : 'or';
      if (Object.keys(value).length !== 1 || !Array.isArray(value[op]) || !value[op].length || value[op].length > 256) error('Invalid logical filter');
      const kinds = new Set(value[op].map(child => filter(child, depth + 1)));
      if (kinds.size !== 1) error('Cube logical filters cannot mix measures and dimensions');
      return [...kinds][0];
    }
    keys(value, ['member', 'operator', 'values'], 'Cube filter');
    const entry = member(value.member, ['measures', 'dimensions'], 'filter');
    const op = value.operator;
    const permitted = BASIC.has(op) || STRING.has(op) && entry.kind === 'dimensions' && entry.type === 'string' ||
      NUMBER.has(op) && (entry.kind === 'measures' || entry.type === 'number') ||
      DATE.has(op) && entry.kind === 'dimensions' && entry.type === 'time' || op === 'measureFilter' && entry.kind === 'measures';
    if (!permitted) error(`Unsupported operator/member type: ${value.member} ${String(op)}`);
    if (WITHOUT_VALUES.has(op)) {
      if (own(value, 'values')) error(`${op} does not take values`);
    } else {
      if (!Array.isArray(value.values) || !value.values.length || value.values.length > 256) error('Filter values must be a nonempty array');
      if (DATE.has(op)) {
        if (['inDateRange', 'notInDateRange'].includes(op)) dateRange(value.values, 'filter date range');
        else {
          if (value.values.length !== 1) error(`${op} requires one date`);
          scalar(value.values[0], ['date'], 'filter date');
          if (value.values[0] === null) error('Filter date cannot be null');
        }
      } else for (const item of value.values) scalar(item, ['enum'], 'filter value');
    }
    return entry.kind;
  };
  const query = report.query;
  list(query.measures, ['measures'], 'measures');
  if (own(query, 'dimensions')) list(query.dimensions, ['dimensions'], 'dimensions', true);
  if (own(query, 'segments')) list(query.segments, ['segments'], 'segments');
  if (own(query, 'filters')) {
    if (!Array.isArray(query.filters) || query.filters.length > 256) error('Invalid filters');
    query.filters.forEach(value => filter(value));
  }
  if (own(query, 'timeDimensions')) {
    if (!Array.isArray(query.timeDimensions) || query.timeDimensions.length > 32) error('Invalid timeDimensions');
    for (const time of query.timeDimensions) {
      keys(time, ['dimension', 'granularity', 'dateRange'], 'single-result time dimension');
      const entry = member(time.dimension, ['dimensions'], 'timeDimensions');
      if (entry.type !== 'time') error(`${time.dimension} must be a time dimension in saved /meta`);
      if (own(time, 'granularity')) {
        const values = parameter(time.granularity) ? inputs[time.granularity.$param]?.values : [time.granularity];
        if (!Array.isArray(values) || !values.length || values.some(value => !entry.granularities.includes(value)))
          error(`Granularity absent from supported time member: ${time.dimension}`);
      }
      if (own(time, 'dateRange')) dateRange(time.dateRange, 'timeDimensions.dateRange');
    }
  }
  if (own(query, 'order')) {
    if (!plain(query.order) && !Array.isArray(query.order)) error('Order must be an object or tuple array');
    const order = Array.isArray(query.order) ? query.order : Object.entries(query.order), seen = new Set();
    if (order.length > 64) error('Too many ordering members');
    for (const pair of order) {
      if (!Array.isArray(pair) || pair.length !== 2 || seen.has(pair[0])) error('Invalid ordering entry');
      member(pair[0], ['measures', 'dimensions'], 'order', true); seen.add(pair[0]);
      const choices = parameter(pair[1]) ? inputs[pair[1].$param]?.values : [pair[1]];
      if (!Array.isArray(choices) || !choices.length || choices.some(value => !['asc', 'desc'].includes(value))) error('Ordering must be asc/desc');
    }
  }
  if (own(query, 'offset')) {
    const bounds = parameter(query.offset) ? inputs[query.offset.$param] : { type: 'integer', min: query.offset, max: query.offset };
    if (bounds?.type !== 'integer' || !Number.isSafeInteger(bounds.min) || !Number.isSafeInteger(bounds.max) || bounds.min < 0) error('Offset requires a nonnegative bounded integer');
  }
  if (own(query, 'timezone')) {
    const zones = parameter(query.timezone) ? inputs[query.timezone.$param]?.values : [query.timezone];
    if (!Array.isArray(zones) || !zones.length) error('Timezone requires a fixed name or enum');
    for (const zone of zones) {
      if (typeof zone !== 'string') error('Timezone names must be strings');
      try { new Intl.DateTimeFormat('en', { timeZone: zone }); } catch { error(`Invalid timezone: ${zone}`); }
    }
  }
  for (const flag of ['total', 'ungrouped', 'renewQuery']) if (own(query, flag) && typeof query[flag] !== 'boolean') error(`${flag} must be a fixed boolean`);
  return [...used.values()].map(value => structuredClone(value));
}

// MIT. SF88 adapter for the original Apache-2.0 x402 Stellar client.
import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { isDeepStrictEqual as same } from 'node:util';

export const SDK_VERSION = '2.28.0';
const I128 = 170141183460469231731687303715884105727n;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const atomic = value => typeof value === 'string' && /^[1-9][0-9]{0,38}$/.test(value) && BigInt(value) <= I128;

export class NativeSignerError extends Error {
  constructor(code) { super(code); this.name = 'NativeSignerError'; this.code = code; }
}
export function requireValue(value, code) { if (!value) throw new NativeSignerError(code); }

async function packageVersion(name, specifier) {
  let directory;
  try { directory = dirname(fileURLToPath(import.meta.resolve(specifier))); }
  catch { throw new NativeSignerError('NATIVE_SDK_NOT_INSTALLED'); }
  for (let depth = 0; depth < 8; depth++) {
    try {
      const value = JSON.parse(await readFile(join(directory, 'package.json'), 'utf8'));
      if (value.name === name) return value.version;
    } catch { /* exported entrypoints may be several directories below package.json */ }
    const parent = dirname(directory);
    if (parent === directory) break;
    directory = parent;
  }
  throw new NativeSignerError('NATIVE_SDK_VERSION_UNAVAILABLE');
}

/** Imports installed source; it does not build, sign, simulate or submit anything. */
export async function loadNativeSdk() {
  const versions = {
    core: await packageVersion('@x402/core', '@x402/core/client'),
    stellar: await packageVersion('@x402/stellar', '@x402/stellar/exact/client'),
  };
  requireValue(Object.values(versions).every(version => version === SDK_VERSION), 'NATIVE_SDK_VERSION_MISMATCH');
  try {
    const [{ x402Client }, { ExactStellarScheme }, { createEd25519Signer }] = await Promise.all([
      import('@x402/core/client'), import('@x402/stellar/exact/client'), import('@x402/stellar'),
    ]);
    requireValue([x402Client, ExactStellarScheme, createEd25519Signer].every(value => typeof value === 'function'),
      'NATIVE_SDK_EXPORTS_UNAVAILABLE');
    return Object.freeze({ x402Client, ExactStellarScheme, createEd25519Signer, versions });
  } catch (error) {
    if (error instanceof NativeSignerError) throw error;
    throw new NativeSignerError('NATIVE_SDK_LOAD_FAILED');
  }
}

/** Input comes from SF31 after SF81 approval. The original SF88 config is host-owned. */
export function validateSigningRequest(input, expected) {
  const { intent, challenge, accepted } = input ?? {};
  const { operation, body } = expected;
  const terms = operation.expect;
  const expectedFlow = terms.paymentFlow === undefined ? 'authorization' : terms.paymentFlow;
  requireValue(object(intent) && object(challenge) && object(accepted), 'NATIVE_SIGNER_INPUT_INVALID');
  requireValue(challenge.x402Version === 2 && object(challenge.resource) &&
    Array.isArray(challenge.accepts) && challenge.accepts.length >= 1 && challenge.accepts.length <= 32,
  'NATIVE_CHALLENGE_INVALID');
  requireValue(challenge.resource.url === new URL(operation.url).href && intent.url === challenge.resource.url &&
    intent.intentId === operation.intentId && intent.method === operation.method,
  'NATIVE_OPERATION_MISMATCH');
  requireValue(intent.bodyPresent === body.present && intent.bodyBytes === body.bytes &&
    intent.bodySha256 === body.sha256, 'NATIVE_REQUEST_BODY_MISMATCH');
  requireValue(accepted.scheme === 'exact' && accepted.network === terms.network &&
    accepted.asset === terms.asset && accepted.payTo === terms.payTo &&
    atomic(accepted.amount) && atomic(terms.maxAtomic) && BigInt(accepted.amount) <= BigInt(terms.maxAtomic),
  'NATIVE_PAYMENT_TERMS_MISMATCH');
  requireValue(Number.isInteger(accepted.maxTimeoutSeconds) && accepted.maxTimeoutSeconds >= 1 &&
    accepted.maxTimeoutSeconds <= (terms.maxTimeoutSeconds ?? 86400), 'NATIVE_TIMEOUT_MISMATCH');
  requireValue(['authorization','upfront'].includes(expectedFlow) &&
    accepted.extra?.areFeesSponsored === true &&
    (accepted.extra?.paymentFlow === undefined ? 'authorization' : accepted.extra.paymentFlow) === expectedFlow,
  'NATIVE_AUTHORIZATION_SPONSORSHIP_REQUIRED');
  requireValue(['scheme', 'network', 'asset', 'payTo', 'amount', 'maxTimeoutSeconds']
    .every(key => intent[key] === accepted[key]) && intent.maxAtomic === terms.maxAtomic &&
    same(intent.acceptedTerms, accepted), 'NATIVE_APPROVED_INTENT_MISMATCH');
  requireValue(challenge.accepts.filter(option => same(option, accepted)).length === 1,
    'NATIVE_SELECTED_OFFER_MISMATCH');
  requireValue(challenge.extensions === undefined || object(challenge.extensions), 'NATIVE_EXTENSIONS_INVALID');
  return { intent: structuredClone(intent), challenge: structuredClone(challenge), accepted: structuredClone(accepted) };
}

/**
 * The native SDK creates and signs the transaction. SF31 owns the signed HTTP
 * retry; SF81/SF36 own human approval and persistent spend reservations.
 * sdk is injectable only by trusted embedding code, never by a seller request.
 */
export async function createNativeBuyerSigner({ signer, expected, rpcUrl, sdk }) {
  sdk ??= await loadNativeSdk();
  requireValue(expected && object(expected.operation) && object(expected.body), 'NATIVE_EXPECTATION_REQUIRED');
  requireValue(['stellar:testnet', 'stellar:pubnet'].includes(expected.operation.expect?.network),
    'NATIVE_NETWORK_INVALID');
  requireValue(typeof expected.payer === 'string' && /^[GC][A-Z2-7]{55}$/.test(expected.payer) &&
    object(signer) && signer.address === expected.payer && typeof signer.signAuthEntry === 'function',
  'NATIVE_PAYER_MISMATCH');
  const fixed = structuredClone(expected);
  const nativeSigner = { address: expected.payer, signAuthEntry: signer.signAuthEntry.bind(signer) };
  if (typeof signer.signTransaction === 'function') nativeSigner.signTransaction = signer.signTransaction.bind(signer);
  const scheme = new sdk.ExactStellarScheme(Object.freeze(nativeSigner), { url: rpcUrl });
  let attempted = false;
  return Object.freeze({
    get readiness() { return Object.freeze({ network: fixed.operation.expect.network, payer: fixed.payer,
      sdkVersions: sdk.versions, provider: 'ORIGINAL_X402_STELLAR', signingAttempts: attempted ? 1 : 0 }); },
    async sign(input) {
      const checked = validateSigningRequest(input, fixed);
      requireValue(!attempted, 'NATIVE_SIGNING_ALREADY_ATTEMPTED');
      attempted = true;
      // A new native client uses exactly the host-approved selected option and
      // its original atomic cap. No USD conversion, fallback rail or extra retry.
      const client = new sdk.x402Client((version, options) => {
        const matches = options.filter(option => same(option, checked.accepted));
        requireValue(version === 2 && matches.length === 1, 'NATIVE_SDK_SELECTION_MISMATCH');
        return matches[0];
      });
      requireValue(typeof client.setSpendControls === 'function', 'NATIVE_SDK_SPEND_CONTROLS_UNAVAILABLE');
      client.register(checked.accepted.network, scheme);
      client.setSpendControls({ allowedAssets: [{ network: checked.accepted.network,
        asset: checked.accepted.asset, maxAmountPerPayment: checked.intent.maxAtomic }] });
      let result;
      try { result = await client.createPaymentPayload(checked.challenge); }
      catch { throw new NativeSignerError('NATIVE_PAYMENT_CREATION_FAILED'); }
      requireValue(object(result) && result.x402Version === 2 && object(result.payload) &&
        same(result.accepted, checked.accepted) && same(result.resource, checked.challenge.resource) &&
        same(result.extensions ?? {}, checked.challenge.extensions ?? {}), 'NATIVE_SDK_ENVELOPE_MISMATCH');
      // Preserve the official complete envelope; never reconstruct signed bytes.
      return result;
    },
  });
}

// MIT. Bounded native SDK diagnostics; transaction and credential values are excluded.
export const NATIVE_SIGNING_DIAGNOSTIC_SCHEMA = 'stellar-forge.native-signing-diagnostic.v1';
const VERSION = '2.28.0';
const PHASES = new Set(['NOT_STARTED','PAYLOAD_CREATION','AUTHORIZATION_SIGNING',
  'TRANSACTION_SIGNING','PAYLOAD_VALIDATION','COMPLETE']);
const NAMES = new Set(['Error','TypeError','RangeError','SyntaxError','AggregateError','AbortError',
  'TimeoutError','FetchError','AxiosError','RpcError','ContractError','SimulationError',
  'SendTransactionError','NoSignatureNeededError']);
const TLS_CODES = new Set(['UNABLE_TO_VERIFY_LEAF_SIGNATURE','UNABLE_TO_GET_ISSUER_CERT',
  'UNABLE_TO_GET_ISSUER_CERT_LOCALLY','DEPTH_ZERO_SELF_SIGNED_CERT','SELF_SIGNED_CERT_IN_CHAIN',
  'CERT_HAS_EXPIRED','CERT_NOT_YET_VALID','CERT_REVOKED','ERR_TLS_CERT_ALTNAME_INVALID',
  'ERR_TLS_HANDSHAKE_TIMEOUT','ERR_TLS_INVALID_PROTOCOL_METHOD','ERR_SSL_WRONG_VERSION_NUMBER',
  'ERR_SSL_TLSV1_ALERT_UNKNOWN_CA','ERR_SSL_SSLV3_ALERT_HANDSHAKE_FAILURE']);
const TIMEOUT_CODES = new Set(['ETIMEDOUT','ESOCKETTIMEDOUT','ECONNABORTED','UND_ERR_CONNECT_TIMEOUT',
  'UND_ERR_HEADERS_TIMEOUT','UND_ERR_BODY_TIMEOUT','ERR_REQUEST_TIMEOUT']);
const NETWORK_CODES = new Set(['ECONNREFUSED','ECONNRESET','EPIPE','ENOTFOUND','EAI_AGAIN','ENETUNREACH',
  'EHOSTUNREACH','ERR_NETWORK','UND_ERR_SOCKET','UND_ERR_DESTROYED','UND_ERR_CLOSED']);
const OTHER_CODES = new Set(['ERR_BAD_REQUEST','ERR_BAD_RESPONSE','ERR_CANCELED','ABORT_ERR',
  'UND_ERR_RESPONSE_STATUS_CODE','UND_ERR_REQ_CONTENT_LENGTH_MISMATCH',
  'UND_ERR_RES_CONTENT_LENGTH_MISMATCH','ERR_INVALID_ARG_TYPE','ERR_INVALID_ARG_VALUE']);
const ALL_CODES = new Set([...TLS_CODES,...TIMEOUT_CODES,...NETWORK_CODES,...OTHER_CODES]);
const CATEGORIES = new Set(['TLS','TIMEOUT','NETWORK','HTTP','SDK']);
const REASONS = new Set(['INPUT_PARAMETERS_INVALID','SPONSORSHIP_REQUIRED',
  'SIMULATION_RESULT_MISSING','SIMULATION_RESTORE_REQUIRED','SIMULATION_FAILED',
  'EXPECTED_SIGNER_MISMATCH','AUTHORIZATION_SIGNATURES_MISSING',
  'CLIENT_NOT_REGISTERED','PAYMENT_FLOW_UNSUPPORTED','PAYMENT_POLICY_REJECTED',
  'PAYMENT_CREATION_ABORTED','SPEND_ASSET_NOT_ALLOWED','SPEND_ATOMIC_CAP_EXCEEDED',
  'SPEND_USD_CAP_EXCEEDED','SDK_ENVELOPE_MISMATCH','SDK_SELECTION_MISMATCH']);
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const read = (value, key) => { try { return value?.[key]; } catch { return undefined; } };
const count = value => Number.isSafeInteger(value) && value >= 0;
const status = value => Number.isInteger(value) && value >= 100 && value <= 599 ? value : undefined;

/**
 * The original x402 2.28.0 client throws plain Error for these branches.
 * Classify only its fixed prefixes; discard all interpolated error text.
 * Pinned upstream blobs: Stellar scheme 93a9e6bc1851c243dedb2ef24e0bc4524de30e00,
 * shared c6215729d11a86aed3b029f8dc5565b8bc2e3e1a,
 * core client 30b534b0966c7e3999c28b0e66d9bc4bdf233c34.
 * These observations never change spend controls, retry or release decisions.
 */
function reasonFor(error) {
  const code=read(error,'code');
  if(code==='NATIVE_SDK_ENVELOPE_MISMATCH')return 'SDK_ENVELOPE_MISMATCH';
  if(code==='NATIVE_SDK_SELECTION_MISMATCH')return 'SDK_SELECTION_MISMATCH';
  const message=read(error,'message');
  if(typeof message!=='string')return undefined;
  // Large RPC messages are never copied into a retained diagnostic.
  const prefix=message.slice(0,256);
  if(prefix.startsWith('Invalid input parameters for creating Stellar payment, cause: '))
    return 'INPUT_PARAMETERS_INVALID';
  if(message==='Exact scheme requires areFeesSponsored to be true')return 'SPONSORSHIP_REQUIRED';
  if(message==='Simulation result is undefined')return 'SIMULATION_RESULT_MISSING';
  if(prefix.startsWith('Stellar simulation result has type "RESTORE" with restorePreamble: '))
    return 'SIMULATION_RESTORE_REQUIRED';
  if(message==='Stellar simulation failed' || prefix.startsWith('Stellar simulation failed with error message: '))
    return 'SIMULATION_FAILED';
  if(prefix.startsWith('Expected to sign with ['))return 'EXPECTED_SIGNER_MISMATCH';
  if(prefix.startsWith('unexpected signer(s) required: ['))return 'AUTHORIZATION_SIGNATURES_MISSING';
  if(prefix.startsWith('No client registered for x402 version: ') ||
    prefix.startsWith('No client registered for scheme: ') ||
    prefix.startsWith('No network/scheme registered for x402 version: '))return 'CLIENT_NOT_REGISTERED';
  if(prefix.startsWith('No payment requirements with a recognized paymentFlow for x402 version: '))
    return 'PAYMENT_FLOW_UNSUPPORTED';
  if(prefix.startsWith('All payment requirements were filtered out by policies for x402 version: '))
    return 'PAYMENT_POLICY_REJECTED';
  if(prefix.startsWith('Payment creation aborted: '))return 'PAYMENT_CREATION_ABORTED';
  if(prefix.startsWith('All payment requirements were rejected by spendControls: only default assets '))
    return 'SPEND_ASSET_NOT_ALLOWED';
  if(prefix.startsWith('All payment requirements were rejected by spendControls.allowedAssets maxAmountPerPayment. '))
    return 'SPEND_ATOMIC_CAP_EXCEEDED';
  if(prefix.startsWith('All payment requirements were rejected by spendControls.maxAmountPerPayment ('))
    return 'SPEND_USD_CAP_EXCEEDED';
  return undefined;
}

function record(error) {
  const name=read(error,'name');
  const out = {name:NAMES.has(name) ? name : 'OtherError'};
  const code = read(error,'code');
  if (ALL_CODES.has(code)) out.code = code;
  const reason=reasonFor(error);
  if(reason!==undefined)out.reason=reason;
  const http = status(read(error,'status')) ?? status(read(error,'statusCode')) ??
    status(read(read(error,'response'),'status'));
  if (http !== undefined) out.httpStatus = http;
  return out;
}

/** Keep error identities and fixed SDK reasons only. Raw messages, stacks and bodies are discarded. */
export function nativeFailureFacts(error) {
  const pending=[error], seen=new Set(), facts=[], identities=new Set();
  let visited=0;
  while(pending.length && visited<16) {
    const item=pending.shift();
    if(item===null || (typeof item!=='object' && typeof item!=='function') || seen.has(item))continue;
    seen.add(item);visited++;
    const fact=record(item), key=JSON.stringify(fact);
    if(!identities.has(key)){identities.add(key);facts.push(fact);}
    const cause=read(item,'cause');
    if(cause!==undefined)pending.push(cause);
    const nested=read(item,'errors');
    if(Array.isArray(nested))for(const child of nested.slice(0,16))pending.push(child);
  }
  if(!facts.length)facts.push({name:'OtherError'});
  const codes=facts.map(item=>item.code);
  const category=codes.some(code=>TLS_CODES.has(code))?'TLS':
    codes.some(code=>TIMEOUT_CODES.has(code)) || facts.some(item=>item.name==='TimeoutError')?'TIMEOUT':
    codes.some(code=>NETWORK_CODES.has(code))?'NETWORK':
    facts.some(item=>item.httpStatus>=400)?'HTTP':'SDK';
  return Object.freeze({category,facts:Object.freeze(facts.map(item=>Object.freeze(item))),
    truncated:pending.length>0});
}

function counters(value) {
  if(!object(value))return undefined;
  const entered=read(value,'entered'),returned=read(value,'returned'),failed=read(value,'failed');
  if(![entered,returned,failed].every(count) || returned+failed>entered)return undefined;
  return Object.freeze({entered,returned,failed});
}

/** Validate a diagnostic crossing the existing SF103 / SF88 / retained-wire boundary. */
export function readNativeSigningDiagnostic(value) {
  try {
    if(!object(value))return undefined;
