    snapshot,
    start(){value.status='RUNNING';value.phase='PAYLOAD_CREATION';},
    returned(){value.payloadReturned=true;value.phase='PAYLOAD_VALIDATION';},
    complete(){value.status='COMPLETE';value.phase='COMPLETE';return snapshot();},
    failed(error){
      value.status='FAILED';
